// Checks the recorded live snapshots; does not rerun the host or manufacture evidence.
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=name=>JSON.parse(readFileSync(new URL(name,import.meta.url),'utf8')).snapshots;
const s={...read('work-regression-20261003.json'),...read('work-regression-followup-20261003.json')};
const p='03012026-1003-4000-8000-000000000011',a='03012026-1003-4000-8000-000000000012',b='03012026-1003-4000-8000-000000000013';
const task=(key,id)=>s[key].tasks.find(t=>t.id===id);
assert.equal(s.regSupportBefore.revision,s.regSupportClarified.revision);
assert.equal(task('regSupportClarified','81ad1904-7696-49ac-9daf-94cfbe309c05').status,'open');
assert.equal(task('regZone',p).defer_until,task('regDate',p).defer_until);
assert.equal(task('regRelease',a).view,'normal');
assert.equal(task('regRelease',b).view,'deferred');
assert.equal(task('regCompletePrereq',b).view,'deferred');
assert.equal(task('regCompletePrereq',b).waiting.length,0);
assert.equal(task('regParentDone',p).status,'done');
assert.equal(task('regReopen',p).status,'open');
assert.equal(task('regReopen',b).view,'deferred');
assert.equal(task('regPrereqReopen',b).waiting[0].id,a);
assert(s.regExpiryBefore.retrieved_at<task('regExpiryBefore',p).defer_until);
assert(s.regExpiryAfter.retrieved_at>=task('regExpiryAfter',p).defer_until);
assert.equal(task('regExpiryAfter',p).view,'normal');
assert.equal(task('regExpiryAfter',a).view,'normal');
assert.equal(task('regExpiryAfter',b).view,'deferred');
assert.equal(task('regExpiryAfter',p).due_at,task('regExpiryBefore',p).due_at);
assert.equal(s.regReplay.tasks.filter(t=>t.title==='Verification 0304: identical retry after lost response').length,1);
assert.equal(task('regDraftSaved','20b3e4f8-e6ac-4118-a43e-a9c83d198453').title,'Verification 0303: preserved unsaved draft');
assert.equal(task('regNormalWait','20b3e4f8-e6ac-4118-a43e-a9c83d198453').title,'Verification 0303: latest correction preserved after Undo');
assert.equal(task('regNormalWait',b).view,'normal');
assert.equal(task('regNormalWait',b).waiting.length,1);
assert.equal(s.regRecommendation.normal_count,14);
assert.equal(task('regManualWait','20b3e4f8-e6ac-4118-a43e-a9c83d198453').manual_wait,'Wait for materials from the fictional contact');
assert.equal(task('regArrival','20b3e4f8-e6ac-4118-a43e-a9c83d198453').manual_wait,null);
assert.equal(task('regArrival','20b3e4f8-e6ac-4118-a43e-a9c83d198453').status,'open');
assert.equal(task('regUndoDeferBefore',p).view,'deferred');
assert.equal(task('regUndoDeferAfter',p).view,'normal');
assert.equal(task('regCompletedAfterExpiry','fe745eaa-52b5-4f06-82ec-01a57a57cc30').view,'completed');
assert.equal(task('regStructuredRecovery','fe745eaa-52b5-4f06-82ec-01a57a57cc30').view,'normal');
assert.equal(s.regPendingRecovery.captures.find(c=>c.text.includes('Verification 0305')).status,'pending');
assert.equal(s.regRecoveryReplay.captures.find(c=>c.text.includes('Verification 0305')).status,'applied');
assert.equal(s.regRecoveryReplay.tasks.filter(t=>t.title.includes('Verification 0305')).length,2);
assert.equal(task('regDetachDates',b).parent_id,null);
assert.equal(task('regDetachDates',b).due_at,task('regDetachDue',b).due_at);
assert.equal(task('regDetachDates',b).defer_until,'2026-10-05T00:00:00.000Z');
console.log('Recorded Work snapshot assertions passed');
